# -*- coding: utf-8 -*-\n# =============================================================================\n# Process Name: Visual Embedding Engine for PixelRAG\n# =============================================================================\n# Description:\n#   Generates semantic embeddings for images and text using CLIP ViT-B/32.\n#   Provides both image-to-text and image-to-image similarity search.\n#\n# File: embedder.py\n# Project: ai-breadboard\n# Package: src.rag.pixel\n# Author: hypo69\n# Copyright: © 2026 hypo69\n# =============================================================================\n\nfrom __future__ import annotations\n\nimport asyncio\nimport hashlib\nimport json\nimport logging\nimport time\nfrom dataclasses import asdict, dataclass, field\nfrom pathlib import Path\nfrom typing import Any, Dict, List, Optional, Tuple\n\nimport numpy as np\nfrom PIL import Image\n\ntry:\n    from sentence_transformers import SentenceTransformer\n    SENTENCE_TRANSFORMERS_AVAILABLE = True\nexcept ImportError:\n    SENTENCE_TRANSFORMERS_AVAILABLE = False\n\n\nlogger = logging.getLogger(__name__)\n\n\n@dataclass\nclass EmbeddingMetadata:\n    \"\"\"Metadata about an embedding.\"\"\"\n    embedding_id: str\n    source_type: str  # 'image', 'text'\n    source_content: str  # Path, URL, or text\n    model_name: str\n    embedding_dim: int\n    timestamp: float\n    content_hash: str\n    cached: bool = False\n    meta: Dict[str, Any] = field(default_factory=dict)\n\n\n@dataclass\nclass ImageEmbedding:\n    \"\"\"Complete image embedding with metadata.\"\"\"\n    embedding_id: str\n    vector: np.ndarray  # (512,) float32\n    metadata: EmbeddingMetadata\n\n    def to_dict(self) -> Dict[str, Any]:\n        \"\"\"Convert to dictionary (excluding numpy array).\"\"\"\n        d = asdict(self)\n        d.pop('vector', None)\n        d['vector_shape'] = self.vector.shape\n        d['vector_norm'] = float(np.linalg.norm(self.vector))\n        return d\n\n\nclass PixelEmbedder:\n    \"\"\"\n    ## hypo69 docblock\n    Visual embedding engine using CLIP ViT-B/32 for semantic image search.\n    \n    Features:\n    - Cross-modal embeddings (text and image in same space)\n    - CPU-optimized inference\n    - Batch processing with memory management\n    - Caching and deduplication\n    - Cosine similarity search\n    \"\"\"\n\n    # Model configuration\n    MODEL_NAME = \"sentence-transformers/clip-ViT-B-32\"\n    EMBEDDING_DIM = 512\n    DEFAULT_BATCH_SIZE = 4\n\n    def __init__(\n        self,\n        cache_dir: Optional[Path] = None,\n        batch_size: int = DEFAULT_BATCH_SIZE,\n        device: str = \"cpu\",\n        auto_normalize: bool = True\n    ) -> None:\n        \"\"\"\n        ## hypo69 docblock\n        Initialize visual embedding engine with lazy model loading.\n\n        Args:\n            cache_dir: Directory for caching model and embeddings\n            batch_size: Batch size for processing multiple images\n            device: Device to use ('cpu' or 'cuda')\n            auto_normalize: Normalize embeddings (required for cosine similarity)\n        \"\"\"\n        if not SENTENCE_TRANSFORMERS_AVAILABLE:\n            raise ImportError(\n                \"sentence-transformers not available. \"\n                \"Install: pip install sentence-transformers\"\n            )\n\n        self.cache_dir = cache_dir or Path(\"models/vision\")\n        self.cache_dir.mkdir(parents=True, exist_ok=True)\n        self.batch_size = batch_size\n        self.device = device\n        self.auto_normalize = auto_normalize\n\n        # Lazy loading\n        self._model: Optional[SentenceTransformer] = None\n        self._embedding_cache: Dict[str, np.ndarray] = {}\n        self._metadata_cache: Dict[str, EmbeddingMetadata] = {}\n\n        # Cache files\n        self.cache_file = self.cache_dir / \"embeddings_cache.json\"\n        self.metadata_file = self.cache_dir / \"embeddings_metadata.json\"\n\n        # Load cache if exists\n        self._load_cache()\n\n    @property\n    def model(self) -> SentenceTransformer:\n        \"\"\"\n        ## hypo69 docblock\n        Lazy-load CLIP model on first access.\n\n        Returns:\n            SentenceTransformer: Loaded model instance\n        \"\"\"\n        if self._model is None:\n            logger.info(f\"Loading model: {self.MODEL_NAME}\")\n            self._model = SentenceTransformer(\n                self.MODEL_NAME,\n                device=self.device,\n                cache_folder=str(self.cache_dir)\n            )\n            logger.info(\n                f\"Model loaded. Embedding dimension: {self.EMBEDDING_DIM}\"\n            )\n        return self._model\n\n    def _load_cache(self) -> None:\n        \"\"\"\n        ## hypo69 docblock\n        Load embeddings cache from disk.\n        \"\"\"\n        try:\n            if self.metadata_file.exists():\n                with open(self.metadata_file, 'r', encoding='utf-8') as f:\n                    metadata_dict = json.load(f)\n                    # Restore metadata objects\n                    self._metadata_cache = {\n                        k: EmbeddingMetadata(**v)\n                        for k, v in metadata_dict.items()\n                    }\n                logger.info(\n                    f\"Loaded {len(self._metadata_cache)} cached embeddings\"\n                )\n        except Exception as e:\n            logger.warning(f\"Failed to load cache: {e}\")\n\n    def _save_cache(self) -> None:\n        \"\"\"\n        ## hypo69 docblock\n        Save embeddings cache to disk.\n        \"\"\"\n        try:\n            # Save metadata\n            metadata_dict = {\n                k: asdict(v) for k, v in self._metadata_cache.items()\n            }\n            with open(self.metadata_file, 'w', encoding='utf-8') as f:\n                json.dump(metadata_dict, f, ensure_ascii=False, indent=2)\n\n            logger.info(\n                f\"Saved {len(self._metadata_cache)} embeddings to cache\"\n            )\n        except Exception as e:\n            logger.error(f\"Failed to save cache: {e}\")\n\n    @staticmethod\n    def _compute_content_hash(content: bytes | str) -> str:\n        \"\"\"\n        ## hypo69 docblock\n        Compute SHA-256 hash of content.\n\n        Args:\n            content: Binary or text content\n\n        Returns:\n            str: Hex-encoded hash (truncated to 16 chars)\n        \"\"\"\n        if isinstance(content, str):\n            content = content.encode('utf-8')\n        return hashlib.sha256(content).hexdigest()[:16]\n\n    def _normalize_embedding(self, embedding: np.ndarray) -> np.ndarray:\n        \"\"\"\n        ## hypo69 docblock\n        L2-normalize embedding vector for cosine similarity.\n\n        Args:\n            embedding: Vector to normalize\n\n        Returns:\n            np.ndarray: Normalized vector\n        \"\"\"\n        if self.auto_normalize:\n            norm = np.linalg.norm(embedding) + 1e-8\n            return (embedding / norm).astype(np.float32)\n        return embedding.astype(np.float32)\n\n    async def embed_image(\n        self,\n        image: Image.Image | Path | str,\n        embedding_id: Optional[str] = None,\n        use_cache: bool = True\n    ) -> ImageEmbedding:\n        \"\"\"\n        ## hypo69 docblock\n        Generate embedding for single image.\n\n        Args:\n            image: PIL Image, file path, or image path string\n            embedding_id: Optional custom ID\n            use_cache: Use cached embedding if available\n\n        Returns:\n            ImageEmbedding: Embedding with metadata\n        \"\"\"\n        # Load image if path provided\n        if isinstance(image, (str, Path)):\n            image_path = Path(image)\n            image_obj = Image.open(image_path).convert('RGB')\n            source = str(image_path)\n        else:\n            image_obj = image\n            source = embedding_id or \"image_object\"\n\n        # Compute content hash\n        image_bytes = image_obj.tobytes()\n        content_hash = self._compute_content_hash(image_bytes)\n\n        # Check cache\n        if use_cache and content_hash in self._metadata_cache:\n            logger.info(f\"Using cached embedding for {source}\")\n            return await self._get_cached_embedding(content_hash)\n\n        # Generate embedding\n        logger.info(f\"Embedding image: {source}\")\n        vector = await asyncio.to_thread(\n            self._embed_image_sync,\n            image_obj\n        )\n\n        # Create metadata\n        embedding_id = embedding_id or f\"img_{content_hash}\"\n        metadata = EmbeddingMetadata(\n            embedding_id=embedding_id,\n            source_type=\"image\",\n            source_content=source,\n            model_name=self.MODEL_NAME,\n            embedding_dim=self.EMBEDDING_DIM,\n            timestamp=time.time(),\n            content_hash=content_hash,\n            cached=False\n        )\n\n        embedding = ImageEmbedding(\n            embedding_id=embedding_id,\n            vector=vector,\n            metadata=metadata\n        )\n\n        # Cache\n        self._embedding_cache[content_hash] = vector\n        self._metadata_cache[content_hash] = metadata\n\n        return embedding\n\n    def _embed_image_sync(self, image: Image.Image) -> np.ndarray:\n        \"\"\"\n        ## hypo69 docblock\n        Synchronous image embedding (for use in asyncio.to_thread).\n\n        Args:\n            image: PIL Image\n\n        Returns:\n            np.ndarray: Normalized 512-dim embedding\n        \"\"\"\n        embedding = self.model.encode(image, convert_to_numpy=True)\n        return self._normalize_embedding(embedding)\n\n    async def embed_text(\n        self,\n        text: str,\n        embedding_id: Optional[str] = None,\n        use_cache: bool = True\n    ) -> np.ndarray:\n        \"\"\"\n        ## hypo69 docblock\n        Generate embedding for text query (e.g., search description).\n\n        Args:\n            text: Text to embed\n            embedding_id: Optional custom ID\n            use_cache: Use cached embedding if available\n\n        Returns:\n            np.ndarray: Normalized 512-dim embedding\n        \"\"\"\n        content_hash = self._compute_content_hash(text)\n\n        # Check cache\n        if use_cache and content_hash in self._metadata_cache:\n            logger.info(f\"Using cached text embedding\")\n            return self._embedding_cache[content_hash].copy()\n\n        # Generate embedding\n        logger.info(f\"Embedding text: {text[:50]}...\")\n        vector = await asyncio.to_thread(\n            self._embed_text_sync,\n            text\n        )\n\n        # Cache\n        metadata = EmbeddingMetadata(\n            embedding_id=embedding_id or f\"txt_{content_hash}\",\n            source_type=\"text\",\n            source_content=text,\n            model_name=self.MODEL_NAME,\n            embedding_dim=self.EMBEDDING_DIM,\n            timestamp=time.time(),\n            content_hash=content_hash,\n            cached=False\n        )\n        self._embedding_cache[content_hash] = vector\n        self._metadata_cache[content_hash] = metadata\n\n        return vector\n\n    def _embed_text_sync(self, text: str) -> np.ndarray:\n        \"\"\"\n        ## hypo69 docblock\n        Synchronous text embedding.\n\n        Args:\n            text: Text to embed\n\n        Returns:\n            np.ndarray: Normalized 512-dim embedding\n        \"\"\"\n        embedding = self.model.encode(text, convert_to_numpy=True)\n        return self._normalize_embedding(embedding)\n\n    async def embed_batch(\n        self,\n        images: List[Image.Image | Path | str],\n        batch_size: Optional[int] = None,\n        use_cache: bool = True\n    ) -> List[ImageEmbedding]:\n        \"\"\"\n        ## hypo69 docblock\n        Generate embeddings for multiple images efficiently.\n\n        Args:\n            images: List of PIL Images or file paths\n            batch_size: Batch size for processing\n            use_cache: Use cached embeddings if available\n\n        Returns:\n            List[ImageEmbedding]: List of embeddings\n        \"\"\"\n        batch_size = batch_size or self.batch_size\n        embeddings = []\n\n        logger.info(\n            f\"Embedding {len(images)} images in batches of {batch_size}\"\n        )\n\n        for i in range(0, len(images), batch_size):\n            batch = images[i:i+batch_size]\n            batch_embeddings = await self._embed_batch_sync(\n                batch,\n                use_cache=use_cache\n            )\n            embeddings.extend(batch_embeddings)\n\n            # Progress\n            processed = min(i + batch_size, len(images))\n            logger.info(f\"  Processed {processed}/{len(images)}\")\n\n        return embeddings\n\n    async def _embed_batch_sync(\n        self,\n        images: List[Image.Image | Path | str],\n        use_cache: bool = True\n    ) -> List[ImageEmbedding]:\n        \"\"\"\n        ## hypo69 docblock\n        Process single batch of images.\n\n        Args:\n            images: Batch of images\n            use_cache: Use cache\n\n        Returns:\n            List[ImageEmbedding]: Batch results\n        \"\"\"\n        embeddings = []\n        image_objects = []\n        paths = []\n\n        for img in images:\n            try:\n                if isinstance(img, (str, Path)):\n                    image_obj = Image.open(img).convert('RGB')\n                    paths.append(str(img))\n                else:\n                    image_obj = img\n                    paths.append(\"image_object\")\n                image_objects.append(image_obj)\n            except Exception as e:\n                logger.error(f\"Failed to load image: {e}\")\n                continue\n\n        # Batch encode\n        if image_objects:\n            vectors = await asyncio.to_thread(\n                self._batch_encode_sync,\n                image_objects\n            )\n\n            for path, vector in zip(paths, vectors):\n                content_hash = self._compute_content_hash(\n                    path.encode('utf-8')\n                )\n                metadata = EmbeddingMetadata(\n                    embedding_id=f\"img_{content_hash}\",\n                    source_type=\"image\",\n                    source_content=path,\n                    model_name=self.MODEL_NAME,\n                    embedding_dim=self.EMBEDDING_DIM,\n                    timestamp=time.time(),\n                    content_hash=content_hash,\n                    cached=use_cache\n                )\n                embedding = ImageEmbedding(\n                    embedding_id=metadata.embedding_id,\n                    vector=vector,\n                    metadata=metadata\n                )\n                embeddings.append(embedding)\n                self._embedding_cache[content_hash] = vector\n                self._metadata_cache[content_hash] = metadata\n\n        return embeddings\n\n    def _batch_encode_sync(self, images: List[Image.Image]) -> np.ndarray:\n        \"\"\"\n        ## hypo69 docblock\n        Synchronous batch encoding.\n\n        Args:\n            images: Batch of PIL Images\n\n        Returns:\n            np.ndarray: Batch embeddings (N, 512)\n        \"\"\"\n        embeddings = self.model.encode(images, convert_to_numpy=True)\n        # Normalize each\n        norms = np.linalg.norm(embeddings, axis=1, keepdims=True) + 1e-8\n        if self.auto_normalize:\n            embeddings = embeddings / norms\n        return embeddings.astype(np.float32)\n\n    async def get_cached_embedding(\n        self,\n        content_hash: str\n    ) -> Optional[np.ndarray]:\n        \"\"\"\n        ## hypo69 docblock\n        Retrieve cached embedding by content hash.\n\n        Args:\n            content_hash: Content hash\n\n        Returns:\n            np.ndarray or None: Cached embedding if available\n        \"\"\"\n        return self._embedding_cache.get(content_hash)\n\n    async def _get_cached_embedding(\n        self,\n        content_hash: str\n    ) -> ImageEmbedding:\n        \"\"\"\n        ## hypo69 docblock\n        Retrieve complete cached embedding.\n\n        Args:\n            content_hash: Content hash\n\n        Returns:\n            ImageEmbedding: Cached embedding\n        \"\"\"\n        metadata = self._metadata_cache[content_hash]\n        vector = self._embedding_cache[content_hash]\n        metadata.cached = True\n        return ImageEmbedding(\n            embedding_id=metadata.embedding_id,\n            vector=vector.copy(),\n            metadata=metadata\n        )\n\n    def similarity_search(\n        self,\n        query_embedding: np.ndarray,\n        candidate_embeddings: np.ndarray,\n        top_k: int = 5\n    ) -> List[Tuple[int, float]]:\n        \"\"\"\n        ## hypo69 docblock\n        Find top-k most similar embeddings using cosine similarity.\n\n        Args:\n            query_embedding: Query vector (512,)\n            candidate_embeddings: Candidate vectors (N, 512)\n            top_k: Number of results\n\n        Returns:\n            List[(index, similarity_score)]: Top-k results\n        \"\"\"\n        # Cosine similarity\n        similarities = np.dot(candidate_embeddings, query_embedding)\n        top_indices = np.argsort(similarities)[::-1][:top_k]\n\n        results = [\n            (int(idx), float(similarities[idx]))\n            for idx in top_indices\n        ]\n        return results\n\n    def clear_cache(self) -> None:\n        \"\"\"\n        ## hypo69 docblock\n        Clear in-memory embedding cache.\n        \"\"\"\n        self._embedding_cache.clear()\n        self._metadata_cache.clear()\n        logger.info(\"Cache cleared\")\n\n    def get_cache_stats(self) -> Dict[str, Any]:\n        \"\"\"\n        ## hypo69 docblock\n        Get cache statistics.\n\n        Returns:\n            Dict: Cache stats\n        \"\"\"\n        return {\n            \"cached_embeddings\": len(self._embedding_cache),\n            \"memory_usage_mb\": (\n                len(self._embedding_cache) * self.EMBEDDING_DIM * 4\n            ) / (1024 * 1024),\n            \"model_loaded\": self._model is not None,\n            \"device\": self.device,\n            \"model_name\": self.MODEL_NAME,\n            \"embedding_dim\": self.EMBEDDING_DIM\n        }\n\n    async def cleanup(self) -> None:\n        \"\"\"\n        ## hypo69 docblock\n        Save cache and cleanup resources.\n        \"\"\"\n        self._save_cache()\n        if self._model is not None:\n            # Optional: Unload model from memory\n            del self._model\n            self._model = None\n        logger.info(\"PixelEmbedder cleaned up\")\n"